    async def promote_policy_branch(
        self,
        policy_id: str,
        branch_id: str,
        *,
        ignore_conflict: typing.Optional[bool] = None,
        comments: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> PolicyBranch:
        """
        Promotes a `DRAFT` or `STAGED` branch to `LIVE` status, replacing the existing live branch. You can only have one `LIVE` branch for a policy at a time.

        If the current `LIVE` branch has been modified since this branch was created, the request returns a `409` conflict error. Use the `ignoreConflict=true` query parameter to promote anyway and overwrite those changes.

        Only applicable to `ACCESS_POLICY` type policies.

        Parameters
        ----------
        policy_id : str
            `id` of the `ACCESS_POLICY`

        branch_id : str
            `id` of the policy branch

        ignore_conflict : typing.Optional[bool]
            If you set it as `true`, the specified branch is promoted, even if the current `LIVE` branch has been modified since the promotion branch was created. Any differences between the two branches are overwritten by the branch that's promoted.

        comments : typing.Optional[str]
            Comments or notes about the lifecycle operation that the branch is affected by

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        PolicyBranch
            Success
        """
        _response = await self._raw_client.promote_policy_branch(
            policy_id, branch_id, ignore_conflict=ignore_conflict, comments=comments, request_options=request_options
        )
        return _response.data

